import{_ as l,a0 as s,w as a,s as d,I as r,x as t,a1 as i,A as o,ao as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const g=JSON.parse('{"title":"Linux中使用rsync——文件和目录排除列表 | LCTT x X-CMD","titleTemplate":false,"description":"Linux中使用rsync——文件和目录排除列表 | LCTT (201412) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux中使用rsync——文件和目录排除列表 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux中使用rsync——文件和目录排除列表 | LCTT (201412) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201412/20141030 rsync Command to Exclude a List of Files and Directories in Linux","title":"Linux中使用rsync——文件和目录排除列表","tag":"201412","desc":""},"relativePath":"201412/20141030 rsync Command to Exclude a List of Files and Directories in Linux.md","filePath":"[post].md"}'),u={name:"201412/20141030 rsync Command to Exclude a List of Files and Directories in Linux.md"};function x(m,n,c,f,y,L){const e=s("Link");return a(),d("div",null,[n[17]||(n[17]=r("h1",{id:"linux中使用rsync——文件和目录排除列表",tabindex:"-1"},[t("Linux中使用rsync——文件和目录排除列表 "),r("a",{class:"header-anchor",href:"#linux中使用rsync——文件和目录排除列表","aria-label":"Permalink to “Linux中使用rsync——文件和目录排除列表”"},"​")],-1)),r("p",null,[n[1]||(n[1]=r("strong",null,"rsync",-1)),n[2]||(n[2]=t("是一个十分有用，而且十分流行的linux工具。它用于备份和恢复文件，也用于对比和同步文件。我们已经在前面的文章讲述了",-1)),i(e,{href:"http://linux.cn/article-4503-1.html"},{default:o(()=>[...n[0]||(n[0]=[t("如何在Linux下使用rsync",-1)])]),_:1}),n[3]||(n[3]=t("，而今天我们将增加一些更为有用的rsync使用技巧。",-1))]),n[18]||(n[18]=p(`<h3 id="排除文件和目录列表" tabindex="-1">排除文件和目录列表 <a class="header-anchor" href="#排除文件和目录列表" aria-label="Permalink to “排除文件和目录列表”">​</a></h3><p>有时候，当我们做大量同步的时候，我们可能想要从同步的文件和目录中排除一个文件和目录的列表。一般来说，像设备文件和某些系统文件，或者像临时文件或者缓存文件这类占据不必要磁盘空间的文件是不合适同步的，这类文件是我们需要排除的。</p><p>首先，让我们创建一个名为“excluded”的文件（当然，你想取什么名都可以），然后将我们想要排除的文件夹或文件写入该文件，一行一个。在我们的例子中，如果你想要对根分区进行完整的备份，你应该排除一些在启动时创建的设备目录和放置临时文件的目录，列表看起来像下面这样：</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/10/rsync-excluded.jpg" alt="rsync excluded"></p><p>然后，你可以运行以下命令来备份系统：</p><pre><code>$ sudo rsync -aAXhv --exclude-from=excluded / /mnt/backup
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/10/rsync-exclude-file.jpg" alt="rsync exclude file"></p><h3 id="从命令行排除文件" tabindex="-1">从命令行排除文件 <a class="header-anchor" href="#从命令行排除文件" aria-label="Permalink to “从命令行排除文件”">​</a></h3><p>你也可以从命令行直接排除文件，该方法在你要排除的文件数量较少，并且在你想要将它写成脚本或加到crontab中又不想脚本或cron依赖于另外一个文件运行时十分有用。</p><p>例如，如果你想要同步/var到一个备份目录，但是你不想要包含cache和tmp这些通常不会有重要内容的文件夹，你可以使用以下命令：</p><pre><code>$ sudo rsync -aAXhv --exclude={&quot;/var/cache&quot;,&quot;/var/tmp&quot;} /var /home/adrian/var
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/10/rsync-exclude.jpg" alt="rsync exclude"></p><p>该命令易于在脚本或cron中使用，也不会依赖其它文件。</p><hr>`,14)),r("p",null,[n[5]||(n[5]=t("via: ",-1)),i(e,{href:"http://linoxide.com/linux-command/exclude-files-rsync-examples/"},{default:o(()=>[...n[4]||(n[4]=[t("http://linoxide.com/linux-command/exclude-files-rsync-examples/",-1)])]),_:1})]),r("p",null,[n[9]||(n[9]=t("作者：",-1)),i(e,{href:"http://linoxide.com/author/adriand/"},{default:o(()=>[...n[6]||(n[6]=[t("Adrian Dinu",-1)])]),_:1}),n[10]||(n[10]=t(" 译者：",-1)),i(e,{href:"https://github.com/GOLinux"},{default:o(()=>[...n[7]||(n[7]=[t("GOLinux",-1)])]),_:1}),n[11]||(n[11]=t(" 校对：",-1)),i(e,{href:"https://github.com/wxy"},{default:o(()=>[...n[8]||(n[8]=[t("wxy",-1)])]),_:1})]),r("p",null,[n[14]||(n[14]=t("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...n[12]||(n[12]=[t("LCTT",-1)])]),_:1}),n[15]||(n[15]=t(" 原创翻译，",-1)),i(e,{href:"http://linux.cn/"},{default:o(()=>[...n[13]||(n[13]=[t("Linux中国",-1)])]),_:1}),n[16]||(n[16]=t(" 荣誉推出",-1))])])}const b=l(u,[["render",x]]);export{g as __pageData,b as default};
